<script setup lang="ts">
import { ArrowRightOutlined, SearchOutlined, PlusOutlined, DownloadOutlined, CheckOutlined, ReadOutlined, CodeOutlined, CheckCircleFilled, FileTextOutlined, LinkOutlined, CloseOutlined } from '@ant-design/icons-vue'
import type { ProblemSummary } from '../../shared/types'
const {data:problems,refresh,error}=await useFetch<ProblemSummary[]>('/api/problems')
const keyword=ref(''),tab=ref('recommended'),category=ref('全部'),status=ref('全部状态')
const categories=['全部','基础语法','数组与字符串','二维数组','函数与递归','综合算法']
const filtered=computed(()=>(problems.value||[]).filter(p=>(tab.value==='all'||(tab.value==='imported'?p.source==='洛谷':p.source==='内置'))&&(category.value==='全部'||p.category===category.value)&&(status.value==='全部状态'||(status.value==='已完成'?p.solvedMips:!p.solvedMips))&&`${p.id} ${p.title} ${p.tags.join(' ')}`.toLowerCase().includes(keyword.value.toLowerCase())))
const builtins=computed(()=>(problems.value||[]).filter(p=>p.source==='内置'))
const solved=computed(()=>builtins.value.filter(p=>p.solvedMips).length)
const next=computed(()=>builtins.value.find(p=>!p.solvedMips)||builtins.value[0])
const imported=computed(()=>(problems.value||[]).filter(p=>p.source==='洛谷').length)
const showImport=ref(false),source=ref(''),importing=ref(false),importError=ref(''),manual=ref(false)
const manualForm=reactive({title:'',description:'',inputFormat:'',outputFormat:'',constraints:'',cExample:''})
async function importProblem(){importError.value='';importing.value=true;try{const r=await $fetch<{id:string}>('/api/'+(manual.value?'manual-import':'import'),{method:'POST',body:{source:source.value,...(manual.value?manualForm:{})}});showImport.value=false;await refresh();await navigateTo('/problems/'+r.id)}catch(e:any){importError.value=e.data?.statusMessage||e.message}finally{importing.value=false}}
const difficultyClass=(d:string)=>d==='入门'?'easy':d==='基础'?'basic':d==='进阶'?'medium':'hard'
</script>
<template>
<div class="page library-page">
 <div class="page-heading"><div><h1>练习题库<span class="heading-dot">.</span></h1></div><a-button type="primary" size="large" @click="showImport=true"><template #icon><PlusOutlined/></template>从洛谷导入</a-button></div>
 <a-alert v-if="error" type="error" show-icon message="题库加载失败" :description="error.message"/>
 <div class="library-layout"><section class="library-content">
 <div v-if="next" class="continue-card"><div class="continue-content"><div class="small-label"><span class="status-dot"/>{{solved?'继续练习':'开始练习'}}</div><h2>{{next.title}}</h2><p>{{next.tags.join(' · ')}}</p><NuxtLink :to="'/problems/'+next.id" class="continue-link">{{solved?'继续练习':'开始第一题'}}<ArrowRightOutlined/></NuxtLink></div><div class="continue-visual" aria-hidden="true"><div class="mini-code-header"><span/><span/><span/><code>main.asm</code></div><div class="mini-code"><span class="code-dim">01</span> <span class="code-purple">.text</span><br><span class="code-dim">02</span> <span class="code-green">main:</span><br><span class="code-dim">03</span> &nbsp; <span class="code-purple">li</span> &nbsp; $v0, <span class="code-orange">5</span><br><span class="code-dim">04</span> &nbsp; <span class="code-purple">syscall</span><br><span class="code-dim">05</span> &nbsp; <span class="code-comment"># 从读取一个数开始</span></div><span class="mini-chip">C → MIPS</span></div></div>
 <div class="problem-browser">
  <div class="browser-tabs" role="tablist" aria-label="题库来源"><button v-for="t in [{id:'recommended',label:'推荐题单',count:builtins.length},{id:'imported',label:'洛谷题库',count:imported},{id:'all',label:'全部题目',count:problems?.length||0}]" :key="t.id" :class="{selected:tab===t.id}" role="tab" :aria-selected="tab===t.id" @click="tab=t.id;category='全部'">{{t.label}}<span>{{t.count}}</span></button></div>
  <div class="filter-bar"><a-input v-model:value="keyword" placeholder="搜索题目、题号或知识点" allow-clear aria-label="搜索题目"><template #prefix><SearchOutlined/></template></a-input><a-select v-model:value="status" aria-label="完成状态" :options="['全部状态','未完成','已完成'].map(value=>({value,label:value}))"/></div>
  <div v-if="tab!=='imported'" class="category-filter" aria-label="知识点筛选"><button v-for="c in categories" :key="c" :class="{selected:category===c}" @click="category=c">{{c}}</button></div>
  <div class="problem-table-wrap"><table class="problem-table"><thead><tr><th class="number-col">序号</th><th>题目</th><th>难度</th><th class="language-col">MIPS</th><th class="action-col"><span class="sr-only">操作</span></th></tr></thead><tbody><tr v-for="(p,i) in filtered" :key="p.id"><td class="mono muted">{{String(i+1).padStart(2,'0')}}</td><td><NuxtLink :to="'/problems/'+p.id" class="problem-title">{{p.title}}</NuxtLink><div class="problem-sub"><span class="mono">{{p.id}}</span><span class="sub-divider"/><span>{{p.tags.join(' / ')}}</span></div></td><td><span :class="['difficulty',difficultyClass(p.difficulty)]">{{p.difficulty}}</span></td><td class="language-col"><CheckCircleFilled v-if="p.solvedMips" class="solved-icon" aria-label="MIPS 已通过"/><span v-else class="unsolved-circle" aria-label="MIPS 未通过"/></td><td class="action-col"><NuxtLink :to="'/problems/'+p.id" class="row-action" :aria-label="'练习'+p.title"><ArrowRightOutlined/></NuxtLink></td></tr></tbody></table></div>
  <div v-if="!filtered.length" class="empty-state"><FileTextOutlined/><h3>{{tab==='imported'&&!imported?'还没有导入的题目':'没有匹配的题目'}}</h3><p>{{tab==='imported'&&!imported?'输入洛谷题号，把题目加入本地题库。':'试试其他关键词或筛选条件。'}}</p><a-button v-if="tab==='imported'&&!imported" @click="showImport=true">导入题目</a-button></div>
  <div class="table-footer"><span>共 {{filtered.length}} 道题目</span></div>
 </div>
 </section><aside class="learning-rail"><section class="rail-card progress-card"><span class="small-label">MIPS 学习进度</span><div class="progress-number">{{solved}}<span>/ {{builtins.length}}</span></div><a-progress :percent="builtins.length?Math.round(solved/builtins.length*100):0" :show-info="false" stroke-color="#31866b" trail-color="#e8eeeb" :stroke-width="5"/></section>
 <section class="rail-card"><h3><ReadOutlined/>学习路线</h3><div class="learning-path"><button v-for="(c,i) in categories.slice(1)" :key="c" :class="{active:category===c}" @click="category=c;tab='recommended'"><span class="path-number">{{i+1}}</span><span><strong>{{c}}</strong><small>{{['读写、运算与条件判断','遍历、计数与简单排序','下标转换与嵌套循环','函数调用与现场保存','按需挑战'][i]}}</small></span></button></div></section>

 <NuxtLink to="/settings" class="settings-link"><span><strong>模型设置</strong><small>生成测试数据</small></span><ArrowRightOutlined/></NuxtLink>
 </aside></div>
 <a-modal v-model:open="showImport" title="从洛谷导入题目" :footer="null" :width="570" :destroy-on-close="false"><div class="modal-content"><a-alert v-if="importError" type="error" show-icon :message="importError"/><a-form layout="vertical" :model="{source}" @finish="importProblem"><a-form-item label="洛谷题号或链接" name="source" :rules="[{required:true,message:'请输入洛谷题号或链接'}]"><a-input v-model:value="source" placeholder="P1001 或 https://www.luogu.com.cn/problem/P1001" :maxlength="200"/></a-form-item><p class="field-note">导入题面与公开样例。</p><button type="button" class="text-button" @click="manual=!manual">{{manual?'切换自动拉取':'手动粘贴题面'}}</button><template v-if="manual"><a-form-item label="题目名称" required><a-input v-model:value="manualForm.title"/></a-form-item><a-form-item label="题目描述" required><a-textarea v-model:value="manualForm.description" :rows="4"/></a-form-item><a-form-item label="输入格式"><a-textarea v-model:value="manualForm.inputFormat" :rows="2"/></a-form-item><a-form-item label="输出格式"><a-textarea v-model:value="manualForm.outputFormat" :rows="2"/></a-form-item><a-form-item label="数据范围"><a-textarea v-model:value="manualForm.constraints" :rows="2"/></a-form-item><a-form-item label="C 代码示例"><a-textarea v-model:value="manualForm.cExample" :rows="8" class="mono" :spellcheck="false"/></a-form-item></template><div class="modal-actions"><a-button @click="showImport=false">取消</a-button><a-button type="primary" html-type="submit" :loading="importing"><template #icon><DownloadOutlined/></template>导入题目</a-button></div></a-form></div></a-modal>
</div>
</template>
